wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::inference_llm;

struct Node;

impl Guest for Node {
    fn run(query: CustomerQuery) -> ModerationResult {
        // `requires len(question) <= 512` holds of every input, so we can hand the
        // question straight to the one capability this node is granted: inference.
        let system = "You are a content-moderation gate for a customer-support system. \
Decide whether the customer's question may proceed. Reply with exactly one line and \
nothing else. Use `OK` if the question is acceptable. Use `VIOLATION: <short reason>` \
if it breaches policy (abuse, hate, harassment, or requests for clearly illegal help) \
and must be refused outright. Use `ESCALATION: <short reason>` if it needs a human \
(credible threats of harm, self-harm, legal or safety risk). Pick exactly one.";

        let verdict = inference_llm::infer(system, &query.question, "moderate");
        let trimmed = verdict.trim();
        let tag = trimmed.to_ascii_uppercase();

        if tag.starts_with("VIOLATION") {
            let reason = extract_reason(trimmed)
                .unwrap_or_else(|| "content policy violation".to_string());
            ModerationResult::Violation(PolicyViolation { reason })
        } else if tag.starts_with("ESCALATION") || tag.starts_with("ESCALATE") {
            let reason = extract_reason(trimmed)
                .unwrap_or_else(|| "requires human review".to_string());
            ModerationResult::Escalation(EscalationRequest { query, reason })
        } else {
            // Default-allow only the clean case; anything unrecognised is treated as OK
            // since the model was asked to tag refusals explicitly.
            ModerationResult::Ok(ModeratedQuery { query })
        }
    }
}

/// Pull the text after the first `:` on the verdict line, if any.
fn extract_reason(line: &str) -> Option<String> {
    line.split_once(':')
        .map(|(_, rest)| rest.trim().to_string())
        .filter(|s| !s.is_empty())
}

export!(Node);
```

