struct Node;

impl Guest for Node {
    fn run(query: CustomerQuery) -> ModerationResult {
        // `requires len(question) <= 512` holds of every input, so the question can
        // be handed straight to the one capability this node is granted: inference.
        let system = "You are a content-moderation gate for a customer-support system. \
