            ModerationResult::Escalation(EscalationRequest { query, reason })
        } else if tag.starts_with("OK") {
            ModerationResult::Ok(ModeratedQuery { query })
        } else {
            // An unrecognised verdict is not a clean pass: route it to a human.
            ModerationResult::Escalation(EscalationRequest {
                query,
                reason: "moderation verdict unclear; requires human review".to_string(),
            })
        }
    }
}

